# Supplement, herbal and complementary medicine guides (21 Nov 2026): the common pharmacy-shelf products (Chemist Warehouse-style range).
# Evidence first: what works, what might, what doesn't (save your money), safety and interactions. Run: python3 _scripts/gen_sheets.py _scripts/sheets/supps_nov26.py
C, U, R = ("c", "Common", "1 in 10 to 1 in 100"), ("u", "Uncommon", "1 in 100 to 1 in 1,000"), ("r", "Rare", "1 in 1,000 to 1 in 10,000")
ODS = ("NIH Office of Dietary Supplements: fact sheets", "https://ods.od.nih.gov/factsheets/list-all/")
NCCIH = ("NCCIH: Herbs at a glance", "https://www.nccih.nih.gov/health/herbsataglance")
TGA = ("TGA: Complementary medicines", "https://www.tga.gov.au/products/complementary-medicines")
COCH = ("Cochrane Library", "https://www.cochranelibrary.com/")
NHMRC = ("NHMRC: Nutrient Reference Values", "https://www.eatforhealth.gov.au/nutrient-reference-values")
SUPP_HUB = ("Supplements: what works", "/medicines/")


def S(slug, h1, short, title, desc, kind, lede, quick, brands, how, works, maybe, no, dose, cost, common, serious, avoid, good, faq, src, related, label="Supplement"):
    def lst(items, mark):
        return "".join('<li><b>%s %s</b><span>%s</span></li>' % (mark, b, t) for b, t in items)
    extra = ('<h2>What the evidence says</h2>\n<p class="evkey">From systematic reviews and large trials where they exist. ✅ good evidence · 🟡 some or mixed evidence · ❌ doesn’t work.</p>\n<ul class="skip evl">'
             + lst(works, "✅") + lst(maybe, "🟡") + lst(no, "❌") + "</ul>\n"
             + ("<h2>Avoid or check first if</h2>\n<ul>%s</ul>\n" % "".join("<li>%s</li>" % a for a in avoid) if avoid else ""))
    ev = "Good for: " + ", ".join(b for b, _ in works) if works else ("Mixed: " + ", ".join(b for b, _ in maybe) if maybe else "Little evidence")
    se = []
    if common: se.append((C[0], C[1], C[2], common))
    if serious: se.append((R[0], R[1], R[2], ["<b>%s</b>" % x for x in serious]))
    med(slug, title, desc, h1, short,
        [("s", kind), ("l", "Complementary medicine (AUST L) or food")],
        lede, quick,
        [("For", ", ".join([b for b, _ in works] + [b for b, _ in maybe]) or "Popular uses with weak evidence"), ("Evidence", ev), ("Cost", cost), ("Dose", dose),
         ("Watch for", "; ".join(common[:2]) if common else "Few side effects at usual doses")],
        "Evidence first, marketing second.",
        brands, how, [b for b, _ in works + maybe] or ["See the evidence section"],
        "Most people have no side effects at usual doses. Supplements can still interact with medicines: tell your doctor and pharmacist what you take.",
        se, ["Signs of an allergic reaction: swelling of the face or throat, trouble breathing (call 000)"] + (["Yellow skin or eyes, dark urine or severe tiredness (possible liver injury)"] if "liver" in " ".join(serious).lower() else []),
        good, faq, src + [TGA], related, index_label=label, extra=extra)


