  [("Colds", "Lozenges started within 24 hours may shorten colds slightly; evidence is uncertain."), ("Acne", "Small benefit in some trials, less than standard treatments.")],
  [("Preventing COVID-19", "No good evidence."), ("Nasal zinc sprays", "Linked to permanent loss of smell: avoid.")],
  "Usually 10 to 25 mg elemental zinc daily. Upper limit for adults: 40 mg a day.",
  "About $10 to $20 a month",
  ["Nausea, especially on an empty stomach", "Metallic taste (lozenges)"],
  ["Copper deficiency with long-term high doses (anaemia, numbness, walking problems)"],
  ["You take antibiotics (tetracyclines, quinolones): separate by at least 2 hours", "You’ve been taking more than 40 mg a day for months"],
  ["Take with food if it makes you nauseous.", "Many ‘immune’ products combine zinc with vitamin C; add up the total zinc you take.", "Never use zinc nasal sprays."],
